-- Schema REFERENZIALE per PostgreSQL/Supabase: revisione/migrazioni necessarie allo sviluppatore.
-- Usare Supabase auth.users e RLS; il catalogo globale è scrivibile soltanto da backend admin sicuro.
create extension if not exists pgcrypto;
create table if not exists public.nutrients (id text primary key, label_it text not null, canonical_unit text not null, nutrient_group text not null, kind text not null, formula jsonb, updated_at timestamptz default now());
create table if not exists public.reference_versions (id text primary key, source text not null, version_label text not null, source_url text, published_at date, verified_at timestamptz, status text not null default 'pending');
create table if not exists public.nutrient_limits (id uuid primary key default gen_random_uuid(), reference_version_id text references public.reference_versions(id), nutrient_id text not null references public.nutrients(id), age_stage text not null, energy_model text, lower_value numeric, upper_value numeric, unit text not null, basis text not null, lower_source_type text, upper_source_type text, limit_class text not null, applicability jsonb default '{}'::jsonb, notes text, unique(reference_version_id,nutrient_id,age_stage,energy_model,limit_class));
create table if not exists public.food_categories (id text primary key, parent_id text references public.food_categories(id), label_it text not null);
create table if not exists public.foods (id text primary key, name_it text not null, category_id text references public.food_categories(id), processing_state text not null default 'unspecified', species_cut text, edible_portion_descriptor text, kcal_me_per_100g numeric, me_calculation_method text, source_identifier text, source_url text, source_version text, data_status text not null default 'unverified', profile_version integer not null default 1, updated_at timestamptz default now());
create table if not exists public.food_nutrients (food_id text not null references public.foods(id), nutrient_id text not null references public.nutrients(id), profile_version integer not null default 1, amount_per_100g numeric, unit text not null, value_status text not null default 'unknown', source_id text, primary key(food_id,nutrient_id,profile_version), check(amount_per_100g is null or amount_per_100g>=0));
create table if not exists public.supplements (id text primary key, name_it text not null, class text, dose_unit text not null, mass_per_unit_g numeric, label_source text, product_variant text, product_version text, status text not null default 'unverified', updated_at timestamptz default now());
create table if not exists public.supplement_nutrients (supplement_id text not null references public.supplements(id), nutrient_id text not null references public.nutrients(id), amount_per_dose numeric, unit text not null, label_basis text, source_id text, value_status text not null default 'unknown', primary key(supplement_id,nutrient_id));
create table if not exists public.user_profiles (user_id uuid primary key references auth.users(id) on delete cascade, display_name text, created_at timestamptz default now());
create table if not exists public.dogs (id uuid primary key default gen_random_uuid(), owner_id uuid not null references auth.users(id), name text not null, breed text, birth_date date, sex text, sterilized boolean, weight_current_kg numeric not null check(weight_current_kg>0), weight_target_kg numeric not null check(weight_target_kg>0), bcs numeric, activity_factor numeric, kcal_target numeric check(kcal_target>0), kcal_source text, macro_targets jsonb default '{}'::jsonb, notes jsonb default '[]'::jsonb, created_at timestamptz default now());
create table if not exists public.dog_weight_log (id uuid primary key default gen_random_uuid(), dog_id uuid references public.dogs(id) on delete cascade, date timestamptz default now(), weight_kg numeric not null check(weight_kg>0));
create table if not exists public.user_prices (id uuid primary key default gen_random_uuid(), owner_id uuid not null references auth.users(id), product_type text not null check(product_type in ('food','supplement')), product_id text not null, supplier text, package_price numeric not null check(package_price>=0), package_quantity numeric not null check(package_quantity>0), package_unit text not null, canonical_price_per_g numeric, currency text default 'EUR', active boolean default true, created_at timestamptz default now());
create table if not exists public.recipes (id uuid primary key default gen_random_uuid(), owner_id uuid not null references auth.users(id), dog_id uuid not null references public.dogs(id) on delete cascade, name text not null, is_primary boolean not null default false, current_version_id uuid, created_at timestamptz default now());
create table if not exists public.recipe_versions (id uuid primary key default gen_random_uuid(), recipe_id uuid not null references public.recipes(id) on delete cascade, revision integer not null, status text not null, suggested_items jsonb not null default '[]'::jsonb, chosen_items jsonb not null default '[]'::jsonb, nutrient_audit jsonb not null default '{}'::jsonb, dependency_snapshot jsonb not null default '{}'::jsonb, kcal_target numeric, notes text, created_at timestamptz default now(), unique(recipe_id,revision));
create table if not exists public.audit_log (id uuid primary key default gen_random_uuid(), actor_id uuid references auth.users(id), entity_name text not null, entity_id text not null, operation text not null, before jsonb, after jsonb, created_at timestamptz default now());
-- IMPORTANT: The next RLS policies cover PRIVATE owner tables; catalog writes should only be via secure admin backend.
alter table public.dogs enable row level security;
alter table public.dog_weight_log enable row level security;
alter table public.user_prices enable row level security;
alter table public.recipes enable row level security;
alter table public.recipe_versions enable row level security;
create policy dogs_own on public.dogs for all to authenticated using (owner_id=auth.uid()) with check (owner_id=auth.uid());
create policy prices_own on public.user_prices for all to authenticated using (owner_id=auth.uid()) with check (owner_id=auth.uid());
create policy recipes_own on public.recipes for all to authenticated using (owner_id=auth.uid() and exists(select 1 from public.dogs d where d.id=dog_id and d.owner_id=auth.uid())) with check (owner_id=auth.uid() and exists(select 1 from public.dogs d where d.id=dog_id and d.owner_id=auth.uid()));
create policy weightlog_own on public.dog_weight_log for all to authenticated using (exists(select 1 from public.dogs d where d.id=dog_id and d.owner_id=auth.uid())) with check (exists(select 1 from public.dogs d where d.id=dog_id and d.owner_id=auth.uid()));
create policy versions_own on public.recipe_versions for all to authenticated using (exists(select 1 from public.recipes r where r.id=recipe_id and r.owner_id=auth.uid())) with check (exists(select 1 from public.recipes r where r.id=recipe_id and r.owner_id=auth.uid()));
-- TODO SECURITY CRITICAL: enable RLS for EVERY PUBLIC reference table and create SELECT-only authenticated policies;
-- no catalog UPDATE/INSERT/DELETE for regular clients. Admin operations via backend service role with secrets outside client.
-- TODO DB: enforce max 10 recipes per dog with transactional trigger; enforce single primary per dog partial unique index;
-- TODO DB: recipe ownership consistency, immutable recipe_versions via trigger, stable food profile history tables;
-- TODO DB: use private schema/role separation, indexes, schema migrations, foreign keys across polymorphic prices.
create unique index if not exists idx_one_primary_recipe_per_dog on public.recipes(dog_id) where is_primary=true;
